+    ++failures;
+    std::printf("FAIL %s: got %lld, want %lld\n", what, got, want);
+}
+
+// 1970-01-06 was a Tuesday: five days after the Thursday epoch.
+std::time_t const tuesdayReset = 5 * 86400;
