+{
+  const x = 60, y = 30;
+  const sky = 'ISSUE-204080';
+  const backdrop = { draw(s) { s.fill(0, 0, s.w, s.h, sky); } };
+  CD.engine.push(backdrop);
+  const c = open(['BAG', 'SAVE', 'EXIT'], { x, y, w: 90 });
