+  const s = render();
+  const mid = at(s, probe[0], probe[1]);
+  assert(CD.gfx.B(mid) > CD.gfx.B(bg), 'the blue behind the window still shows through');
+  assert(CD.gfx.R(mid) > CD.gfx.R(bg), 'and the paper is coming through too');
